'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { UserCheck, Clock, UserX, User, ArrowLeft, CheckCircle2 } from 'lucide-react';
import api from '@/lib/api';

export default function CandidatesPage() {
  const [candidates, setCandidates] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = () => {
    api.get('/admin/candidates')
      .then(res => {
        setCandidates(res.data.candidates);
        setLoading(false);
      })
      .catch(err => {
        console.error('Failed to fetch candidates', err);
        setLoading(false);
      });
  };

  const handleApprove = async (candidateId: string) => {
    try {
      await api.patch(`/admin/candidates/${candidateId}/approve`);
      // Update local state
      setCandidates(prev => 
        prev.map(c => c._id === candidateId ? { ...c, status: 'APPROVED' } : c)
      );
    } catch (err) {
      console.error(err);
      alert('Failed to approve candidate');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <div className="max-w-7xl mx-auto px-6 py-12">
        <div className="flex justify-between items-center mb-10">
          <div>
            <div className="flex items-center space-x-3 mb-2">
              <Link href="/admin/exams" className="p-2 bg-white rounded-full border border-slate-200 hover:bg-slate-100 transition">
                <ArrowLeft className="w-5 h-5 text-slate-600" />
              </Link>
              <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">Candidates</h1>
            </div>
            <p className="text-slate-500">Manage candidate registrations and approvals.</p>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 text-sm font-semibold text-slate-600 uppercase tracking-wider">Name</th>
                  <th className="px-6 py-4 text-sm font-semibold text-slate-600 uppercase tracking-wider">Email</th>
                  <th className="px-6 py-4 text-sm font-semibold text-slate-600 uppercase tracking-wider">Status</th>
                  <th className="px-6 py-4 text-sm font-semibold text-slate-600 uppercase tracking-wider text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {candidates.length > 0 ? candidates.map((candidate) => (
                  <tr key={candidate._id} className="hover:bg-slate-50 transition">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold mr-3">
                          {candidate.name.charAt(0).toUpperCase()}
                        </div>
                        <span className="font-semibold text-slate-800">{candidate.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-slate-600">{candidate.email}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wide
                        ${candidate.status === 'APPROVED' ? 'bg-emerald-100 text-emerald-700' : 
                          candidate.status === 'PENDING_VERIFICATION' ? 'bg-amber-100 text-amber-700' : 
                          'bg-slate-100 text-slate-600'}`}>
                        {candidate.status === 'APPROVED' && <CheckCircle2 className="w-3.5 h-3.5 mr-1" />}
                        {candidate.status === 'PENDING_VERIFICATION' && <Clock className="w-3.5 h-3.5 mr-1" />}
                        {candidate.status === 'PENDING_VERIFICATION' ? 'PENDING' : candidate.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {candidate.status !== 'APPROVED' && (
                        <button
                          onClick={() => handleApprove(candidate._id)}
                          className="inline-flex items-center px-3 py-1.5 bg-emerald-600 text-white text-sm font-medium rounded-lg hover:bg-emerald-700 transition"
                        >
                          <UserCheck className="w-4 h-4 mr-1.5" />
                          Approve
                        </button>
                      )}
                    </td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                      <User className="w-12 h-12 text-slate-300 mx-auto mb-3" />
                      No candidates found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, Suspense } from 'react';
import { useParams, useRouter } from 'next/navigation';
import api from '@/lib/api';
import { Shield, FileVideo, Camera, ArrowLeft } from 'lucide-react';

function EvidenceContent() {
  const { attemptId } = useParams();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [chunks, setChunks] = useState<{ fileUrl: string; chunkIndex: number; createdAt: string }[]>([]);
  const [snapshots, setSnapshots] = useState<{ fileUrl: string; severity: string; description: string }[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    // In a real app we'd fetch both chunks and snapshots.
    // For Phase 11, we fetch playback chunks from the API.
    const fetchEvidence = async () => {
      try {
        const attemptsReq = await api.get('/admin/live'); // Get recording sessions
        // For Phase 11 MVP, we query the exact playback endpoint directly
        // Assuming attemptId points to a recording session ID directly for now, or we'd resolve it
        const res = await api.get(`/recordings/${attemptId}/playback`);
        setChunks(res.data.chunks || []);
        setLoading(false);
      } catch (err) {
        setError('Failed to load evidence or no recordings found.');
        setLoading(false);
      }
    };
    fetchEvidence();
  }, [attemptId]);

  return (
    <div className="p-8 bg-slate-50 min-h-screen">
      <div className="max-w-6xl mx-auto">
        <button onClick={() => router.back()} className="flex items-center text-blue-600 mb-6 font-bold hover:underline">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back to Monitoring
        </button>

        <h1 className="text-3xl font-black text-slate-800 mb-8 flex items-center">
          <Shield className="w-8 h-8 mr-3 text-purple-600" /> Evidence Review
        </h1>

        {error && (
          <div className="bg-red-50 text-red-600 p-4 rounded-lg font-bold mb-6">
            {error}
          </div>
        )}

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mb-8">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h2 className="font-bold text-slate-700 flex items-center">
              <FileVideo className="w-5 h-5 mr-2" /> Video Recordings
            </h2>
          </div>
          <div className="p-6">
            {chunks.length === 0 ? (
              <p className="text-slate-500 italic">No video chunks available yet.</p>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {chunks.map((c, i) => (
                  <div key={i} className="rounded-lg overflow-hidden border border-slate-200">
                    <div className="bg-slate-800 text-slate-300 text-xs p-2 flex justify-between">
                      <span>Chunk #{c.sequence}</span>
                      <span>{Math.round(c.duration / 1000)}s</span>
                    </div>
                    <video controls src={c.url} className="w-full aspect-video bg-black" />
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default function EvidencePage() {
  return (
    <Suspense fallback={<div className="p-10 font-bold">Loading...</div>}>
      <EvidenceContent />
    </Suspense>
  );
}

'use client';

import React, { useEffect, useState, Suspense } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, UserPlus, CheckCircle, Search } from 'lucide-react';
import api from '@/lib/api';

function CandidateAssignmentContent() {
  const params = useParams();
  const examId = params.id as string;

  const [exam, setExam] = useState<{ id: string; title: string; duration: number } | null>(null);
  const [candidates, setCandidates] = useState<{ userId: { _id?: string; id?: string }; status: string }[]>([]);
  const [allUsers, setAllUsers] = useState<{ id: string; _id: string; name: string; email: string; role: string; status: string }[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, [examId]);

  async function fetchData() {
    try {
      const [examRes, assignRes, usersRes] = await Promise.all([
        api.get(`/admin/exams/${examId}`),
        api.get(`/admin/exams/${examId}/candidates`),
        api.get(`/admin/candidates`)
      ]);
      setExam(examRes.data.exam);
      setCandidates(assignRes.data.candidates);
      setAllUsers(usersRes.data.candidates);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  const handleAssign = async (userId: string) => {
    try {
      await api.post(`/admin/exams/${examId}/assign`, { candidateId: userId });
      fetchData();
    } catch (err: unknown) {
      const msg = (err as { response?: { data?: { message?: string } } })?.response?.data?.message;
      alert(msg || 'Failed to assign candidate');
    }
  };

  const isAssigned = (userId: string) => {
    return candidates.some(c => {
      const cid = c.candidateId;
      if (cid && typeof cid === 'object') return String(cid._id) === userId;
      return String(cid) === userId;
    });
  };

  if (loading) return <div className="p-10 text-center font-bold">Loading...</div>;

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-6">
      <div className="max-w-6xl mx-auto">
        <Link href="/admin/exams" className="text-blue-600 font-bold flex items-center mb-6 hover:underline">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back to Exams
        </Link>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900">Assign Candidates</h1>
            <p className="text-slate-500 font-medium mt-1">{exam?.title}</p>
          </div>
          <div className="flex items-center space-x-4">
            <button
              onClick={async () => {
                if (confirm('Are you sure you want to allow all assigned candidates to re-write this exam?')) {
                  try {
                    const res = await api.post(`/admin/exams/${examId}/allow-rewrite-all`);
                    alert(res.data.message);
                    fetchData();
                  } catch (err) {
                    alert('Failed to grant rewrite');
                  }
                }
              }}
              className="px-4 py-2 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg transition"
            >
              Allow Re-write for All
            </button>
            <div className="bg-slate-100 text-slate-600 px-4 py-2 rounded-lg font-bold border border-slate-200">
              {candidates.length} Assigned
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Available Users List */}
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 font-bold text-slate-700 flex justify-between items-center">
              Available Candidates
              <div className="relative">
                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
                <input type="text" placeholder="Search..." className="pl-9 pr-4 py-2 text-sm border border-slate-300 rounded-md focus:ring-blue-500 outline-none" />
              </div>
            </div>
            <div className="overflow-y-auto max-h-[500px]">
              {allUsers.map(user => (
                <div key={user._id} className="flex items-center justify-between p-4 border-b border-slate-100 hover:bg-slate-50">
                  <div>
                    <p className="font-bold text-slate-800">{user.name}</p>
                    <p className="text-sm text-slate-500">{user.email}</p>
                  </div>
                  {isAssigned(user._id) ? (
                    <span className="flex items-center text-sm font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">
                      <CheckCircle className="w-4 h-4 mr-1" /> Assigned
                    </span>
                  ) : (
                    <button onClick={() => handleAssign(user._id)} className="px-3 py-1.5 text-sm bg-blue-600 text-white font-semibold rounded hover:bg-blue-700 transition flex items-center">
                      <UserPlus className="w-4 h-4 mr-1" /> Assign
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Assigned Candidates */}
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-emerald-50 font-bold text-emerald-800">
              Assigned to Exam
            </div>
            <div className="overflow-y-auto max-h-[500px]">
              {candidates.length === 0 ? (
                <div className="p-10 text-center text-slate-500 font-medium">No candidates assigned yet.</div>
              ) : (
                candidates.map(assignment => (
                  <div key={assignment._id} className="flex items-center justify-between p-4 border-b border-slate-100 hover:bg-slate-50">
                    <div>
                      <p className="font-bold text-slate-800">{assignment.candidateId?.name || 'Unknown'}</p>
                      <p className="text-sm text-slate-500">{assignment.candidateId?.email || 'Unknown'}</p>
                    </div>
                    <div className="text-right">
                      <span className="text-xs font-bold uppercase tracking-wider text-slate-500 bg-slate-100 px-2 py-1 rounded">
                        {assignment.status}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

export default function CandidateAssignmentPage() {
  return (
    <Suspense fallback={<div className="p-10 font-bold">Loading...</div>}>
      <CandidateAssignmentContent />
    </Suspense>
  );
}

'use client';

import React, { useEffect, useState, Suspense } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Plus, Save, Trash2 } from 'lucide-react';
import api from '@/lib/api';

function QuestionBuilderContent() {
  const params = useParams();
  const router = useRouter();
  const examId = params.id as string;

  const [exam, setExam] = useState<{ id: string; title: string; duration: number } | null>(null);
  const [questions, setQuestions] = useState<{ _id?: string; id?: string; text: string; type: string; category: string; marks: number; options: { id: string; text: string }[]; correctAnswer: string }[]>([]);
  const [loading, setLoading] = useState(true);

  // New question form state
  const [showForm, setShowForm] = useState(false);
  const [newQuestion, setNewQuestion] = useState({
    text: '',
    type: 'SINGLE_CHOICE',
    category: 'General',
    marks: 1,
    negativeMarks: 0,
    options: [{ id: 'A', text: '' }, { id: 'B', text: '' }, { id: 'C', text: '' }, { id: 'D', text: '' }],
    correctAnswer: 'A'
  });

  useEffect(() => {
    fetchData();
  }, [examId]);

  async function fetchData() {
    try {
      const [examRes, qRes] = await Promise.all([
        api.get(`/admin/exams/${examId}`),
        api.get(`/admin/exams/${examId}/questions`)
      ]);
      setExam(examRes.data.exam);
      setQuestions(qRes.data.questions);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  const handleAddQuestion = async () => {
    if (!newQuestion.text) return alert('Question text is required');
    try {
      await api.post(`/admin/exams/${examId}/questions`, newQuestion);
      setShowForm(false);
      setNewQuestion({ ...newQuestion, text: '', options: [{ id: 'A', text: '' }, { id: 'B', text: '' }, { id: 'C', text: '' }, { id: 'D', text: '' }] });
      fetchData();
    } catch (err) {
      alert('Failed to add question');
    }
  };

  const handleDelete = async (qId: string) => {
    if (confirm('Delete this question?')) {
      try {
        await api.delete(`/admin/questions/${qId}`);
        fetchData();
      } catch (err) {
        alert('Failed to delete question');
      }
    }
  };

  if (loading) return <div className="p-10 text-center font-bold">Loading...</div>;

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-6">
      <div className="max-w-5xl mx-auto">
        <Link href="/admin/exams" className="text-blue-600 font-bold flex items-center mb-6 hover:underline">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back to Exams
        </Link>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900">Exam Builder</h1>
            <p className="text-slate-500 font-medium mt-1">{exam?.title}</p>
          </div>
          <div className="flex space-x-3">
            <div className="bg-slate-100 text-slate-600 px-4 py-2 rounded-lg font-bold border border-slate-200">
              {questions.length} Questions
            </div>
            {exam?.status === 'DRAFT' && !showForm && (
              <button 
                onClick={() => setShowForm(true)}
                className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-blue-700 transition flex items-center"
              >
                <Plus className="w-4 h-4 mr-2" /> Add Question
              </button>
            )}
          </div>
        </div>

        {showForm && (
          <div className="bg-white p-6 rounded-2xl shadow-md border border-blue-200 mb-8">
            <h3 className="text-lg font-bold text-slate-800 mb-4">New Multiple Choice Question</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Question Text</label>
                <textarea 
                  className="w-full border-slate-300 rounded-lg p-3 border focus:ring-2 focus:ring-blue-500 outline-none" 
                  rows={3}
                  value={newQuestion.text}
                  onChange={e => setNewQuestion({...newQuestion, text: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                {newQuestion.options.map((opt, idx) => (
                  <div key={opt.id}>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Option {opt.id}</label>
                    <input 
                      type="text"
                      className="w-full border-slate-300 rounded-lg p-2 border focus:ring-2 focus:ring-blue-500 outline-none"
                      value={opt.text}
                      onChange={e => {
                        const newOpts = [...newQuestion.options];
                        newOpts[idx].text = e.target.value;
                        setNewQuestion({...newQuestion, options: newOpts});
                      }}
                    />
                  </div>
                ))}
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Correct Answer</label>
                  <select 
                    className="w-full border-slate-300 rounded-lg p-2 border outline-none"
                    value={newQuestion.correctAnswer}
                    onChange={e => setNewQuestion({...newQuestion, correctAnswer: e.target.value})}
                  >
                    {newQuestion.options.map(opt => <option key={opt.id} value={opt.id}>Option {opt.id}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Marks</label>
                  <input type="number" className="w-full border-slate-300 rounded-lg p-2 border outline-none" value={newQuestion.marks} onChange={e => setNewQuestion({...newQuestion, marks: Number(e.target.value)})} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Category</label>
                  <input type="text" className="w-full border-slate-300 rounded-lg p-2 border outline-none" value={newQuestion.category} onChange={e => setNewQuestion({...newQuestion, category: e.target.value})} />
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button onClick={() => setShowForm(false)} className="px-4 py-2 text-slate-600 font-semibold border border-slate-200 rounded-lg hover:bg-slate-50 transition">Cancel</button>
                <button onClick={handleAddQuestion} className="px-4 py-2 bg-emerald-600 text-white font-semibold rounded-lg hover:bg-emerald-700 transition flex items-center">
                  <Save className="w-4 h-4 mr-2" /> Save Question
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="space-y-4">
          {questions.map((q, idx) => (
            <div key={q._id} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm relative group">
              <div className="flex justify-between items-start mb-4">
                <div className="flex items-center space-x-3">
                  <span className="w-8 h-8 rounded-full bg-slate-100 text-slate-600 font-bold flex items-center justify-center border border-slate-200">
                    {idx + 1}
                  </span>
                  <span className="text-xs font-bold uppercase text-slate-500 bg-slate-100 px-2 py-1 rounded">{q.category}</span>
                  <span className="text-xs font-bold uppercase text-blue-600 bg-blue-50 px-2 py-1 rounded border border-blue-100">{q.marks} Mark(s)</span>
                </div>
                {exam?.status === 'DRAFT' && (
                  <button onClick={() => handleDelete(q._id)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition">
                    <Trash2 className="w-5 h-5" />
                  </button>
                )}
              </div>
              <p className="text-lg text-slate-800 font-medium mb-4">{q.text}</p>

              <div className="grid grid-cols-2 gap-3">
                {q.options.map((opt: { id: string; text: string }) => (
                  <div key={opt.id} className={`p-3 rounded-lg border text-sm font-medium ${q.correctAnswer === opt.id ? 'border-emerald-500 bg-emerald-50 text-emerald-800' : 'border-slate-200 bg-slate-50 text-slate-600'}`}>
                    <span className="font-bold mr-2">{opt.id}.</span> {opt.text}
                  </div>
                ))}
              </div>
            </div>
          ))}
          {questions.length === 0 && !showForm && (
            <div className="text-center py-16 bg-white rounded-xl border border-dashed border-slate-300">
              <p className="text-slate-500 font-medium mb-4">This exam has no questions yet.</p>
