        <main className="flex-1 p-8 overflow-y-auto z-10 custom-scrollbar">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {Object.values(candidates).map(candidate => (
