              </div>
            </div>

            {/* Proctoring Summary */}
            <div className="border-t border-slate-200 pt-8">
              <h3 className="text-xl font-bold text-slate-800 flex items-center mb-6">
                <ShieldAlert className="w-6 h-6 text-indigo-500 mr-2" /> Proctoring Summary
